def getv(d, k, default=None):
    if isinstance(d, dict):
        return d.get(k, default)
    return default

def text(x):
    if x is None:
        return ''
    if isinstance(x, (list, tuple, set)):
        return ' '.join([text(v) for v in x]).lower()
    if isinstance(x, dict):
        return ' '.join([text(v) for v in x.values()]).lower()
    return str(x).lower()

def need(task_type):
    s = text(task_type)
    if 'clean' in s:
        return 'clean'
    if 'heat' in s:
        return 'heat'
    if 'cool' in s:
        return 'cool'
    if 'slice' in s:
        return 'slice'
    return ''

def has_take(adm, target, locs, count, holding, bad_action):
    for a in adm:
        s = text(a)
        if s.startswith('take ') and target and target in s and ' from ' in s and not bad_action:
            ok = True
            for loc in locs:
                if loc and loc in s:
                    ok = False
            if ok and count == 0 and not holding:
                return True
    return False

def has_put(adm, target, dest, holding):
    for a in adm:
        s = text(a)
        if s.startswith('put ') and target and target in s and dest and dest in s and holding:
            return True
    return False

def hook(ctx, nb):
    task = ctx.get('task') or {}
    world = ctx.get('world') or {}
    adm = ctx.get('admissible') or []
    ttype = getv(task, 'task_type', getv(ctx, 'task.task_type', ''))
    target = text(getv(task, 'target_type', getv(ctx, 'task.target_type', ''))).strip()
    dest = text(getv(task, 'destination_type', getv(ctx, 'task.destination_type', ''))).strip()
    tt = text(ttype)
    need_op = need(ttype)
    if not need_op:
        nb['transformed'] = True
    prop = getv(world, 'placed_count', getv(ctx, 'world.placed_count', 0))
    if isinstance(prop, str) and prop.isdigit():
        prop = int(prop)
    pc = int(nb.get('placed_count', 0))
    if isinstance(prop, int) and prop > pc:
        pc = prop
    items = getv(world, 'placed_items', getv(ctx, 'world.placed_items', []))
    places = getv(world, 'placed_locations', getv(ctx, 'world.placed_locations', []))
    if isinstance(items, (list, tuple, set)):
        vals = []
        for v in items:
            s = text(v)
            if s and s not in vals:
                vals.append(s)
        nb['placed_items'] = vals[:5]
    if isinstance(places, (list, tuple, set)):
        vals = []
        for v in places:
            s = text(v)
            if s and s not in vals:
                vals.append(s)
        nb['placed_locations'] = vals[:5]
    if need_op and target and target in tt and 'transformed' not in nb:
        nb['transformed'] = True
    actd = ctx.get('action') or {}
    act = text(getv(actd, 'final_action', getv(actd, 'normalized', getv(actd, 'raw', getv(ctx, 'action.final_action', getv(ctx, 'action.raw', ''))))))
    bad_action = bool(getv(ctx, 'action.in_admissible', None) is False or getv(ctx, 'predicates.action_not_admissible', False))
    if need_op and target and act.startswith(need_op + ' ') and target in act and not bad_action:
        nb['transformed'] = True
    inv = text(getv(world, 'inventory', getv(ctx, 'world.inventory', '')))
    holding = bool(target and target in inv and 'not carrying' not in inv and 'nothing' not in inv)
    holding = holding or bool(nb.get('holding_target', False))
    target_take = has_take(adm, target, nb.get('placed_items', []), pc, holding, bad_action)
    if target_take and not holding:
        holding = True
    put_ok = has_put(adm, target, dest, holding)
    wrong = bool(inv and target and not holding and 'nothing' not in inv and 'not carrying' not in inv and 'empty' not in inv)
    if target_take and not holding and not wrong:
        stage = 'take_target'
    elif wrong:
        stage = 'wrong_inventory'
    elif holding and need_op and not nb.get('transformed', False):
        stage = 'transform'
    elif holding and put_ok:
        stage = 'put_target'
    elif holding and (dest and dest in tt or 'destination' in tt) and not put_ok:
        stage = 'go_destination'
    else:
        stage = 'find_target'
    nb['stage'] = stage
    nb['holding_target'] = holding
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = tt
    nb['need_op'] = need_op
    return None

def hook(ctx, nb):
    stage = nb.get('stage')
    target = nb.get('target_type') or 'target'
    dest = nb.get('destination_type') or 'destination'
    need = nb.get('need_op') or 'transform'
    msg = ''
    if stage == 'take_target':
        msg = 'A target ' + target + ' is available here. Take it before closing containers, searching elsewhere, or checking inventory.'
    elif stage == 'transform':
        msg = 'You are carrying the target. Use the admissible ' + need + ' action before any destination put.'
    elif stage == 'go_destination':
        msg = 'You are carrying the target. Go to a ' + dest + ' and put it there; do not put it on other receptacle types.'
    elif stage == 'put_target':
        msg = 'A destination put for the target is available now. Put the ' + target + ' in or on the ' + dest + '.'
    elif stage == 'wrong_inventory':
        msg = 'The carried object is not the target type. Do not place it at the destination; recover and find the target instead.'
    if not msg:
        return None
    key = stage + ':' + msg[:70]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}
